SELECT brand_id AS brandId, brand_name AS brandName, seller_id AS sellerId 
FROM brand 
WHERE brand_name = #{brandName}

SELECT brand_id AS brandId, brand_name AS brandName, seller_id AS sellerId 
FROM brand 
WHERE seller_id = #{sellerId}

SELECT '{ "count":' || COUNT(*) || ' }' AS jsonResult 
FROM brand 
WHERE brand_name = #{brandName}
